def assign_clusters(points: list[list[float]], centroids: list[list[float]]) -> list[int]:
    out: list[int] = []
    dim: int = len(centroids[0])
    for p in range(len(points)):
        best: int = 0
        best_d: float = 1e18
        for c in range(len(centroids)):
            d: float = 0.0
            for k in range(dim):
                diff: float = points[p][k] - centroids[c][k]
                d += diff * diff
            if d < best_d:
                best_d = d
                best = c
        out.append(best)
    return out

